<!DOCTYPE html><html lang="es"><head>@include('partials.favicon')<meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="csrf-token" content="{{ csrf_token() }}"><title>CODEPLAY - Trivia de clase</title><link rel="stylesheet" href="{{ asset('vendor/fontawesome/css/all.min.css') }}"><link href="{{ asset('vendor/fonts/pixel-roboto-400-700.css') }}" rel="stylesheet"><style>
:root{--green:#00f5a0;--panel:#092126;--line:rgba(123,238,207,.32);--muted:#abc3be;--gold:#f1ce70;--red:#ff7580}*{box-sizing:border-box}body{margin:0;min-height:100vh;color:#f3fffb;font-family:Roboto;background:#041519}.page{width:min(1150px,calc(100% - 24px));margin:auto;padding:24px 0}.back{display:inline-flex;padding:10px 14px;border:1px solid var(--line);border-radius:10px;color:white;text-decoration:none}.meta,.panel,.ranking{border:1px solid var(--line);border-radius:17px;background:var(--panel)}.meta{display:flex;justify-content:space-between;gap:12px;flex-wrap:wrap;padding:15px 19px;margin:18px 0}.layout{display:grid;grid-template-columns:1fr 300px;gap:16px}.panel{padding:23px;min-height:500px;text-align:center}.ranking{padding:18px;height:max-content}.timer{display:grid;place-items:center;width:65px;height:65px;border:3px solid var(--gold);border-radius:50%;margin:12px auto;color:var(--gold);font-size:24px;font-weight:900}h1{font-family:'Press Start 2P';line-height:1.55;font-size:clamp(18px,3vw,29px)}.options{display:grid;grid-template-columns:1fr 1fr;gap:10px;text-align:left}.option{padding:13px;border:1px solid var(--line);border-radius:10px}.option:has(input:checked){border-color:var(--green);background:rgba(0,245,160,.1)}input[type=text]{width:100%;padding:13px;background:#06191d;color:white;border:1px solid var(--line);border-radius:10px}.btn{width:100%;padding:12px;border:0;border-radius:10px;background:var(--green);color:#032019;font-weight:900;margin-top:12px}.feedback{padding:19px;border-radius:13px}.correct{background:rgba(24,142,91,.42)}.incorrect{background:rgba(167,52,63,.4)}.rank{display:grid;grid-template-columns:32px 1fr auto;gap:7px;padding:10px;border-bottom:1px solid var(--line)}.points{color:var(--green);font-weight:900}.muted{color:var(--muted)}@media(max-width:800px){.layout{grid-template-columns:1fr}.options{grid-template-columns:1fr}}
</style></head><body><main class="page"><a class="back" href="{{ route('alumno.tests.clase') }}">← Actividades de clase</a><section class="meta"><div><strong>{{ $sesion->configuracion['titulo'] ?? 'Trivia de clase' }}</strong><br><span class="muted">{{ $sesion->clase->nombre }}</span></div><span id="connection">Conectando…</span></section><div class="layout"><section class="panel" id="board"></section><aside class="ranking"><h2>Clasificación</h2><p class="muted">Se actualiza después de cada pregunta.</p><div id="ranking"></div></aside></div></main><script>
const initial=@json($estado),stateUrl=@json(route('tests.live.state',$sesion)),answerUrl=@json(route('tests.live.answer',$sesion)),reconnectUrl=@json(route('tests.live.reconnect',$sesion)),csrf=document.querySelector('meta[name="csrf-token"]').content,tokenKey='codeplay-live-token-{{ $sesion->id }}';@if($token)localStorage.setItem(tokenKey,@json($token));@endif let last='';const esc=v=>String(v??'').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));
function label(v,q){const k=String(v);return q.opciones?.[k]??(['1','true'].includes(k.toLowerCase())?'Verdadero':['0','false'].includes(k.toLowerCase())?'Falso':k)}
function render(d){document.getElementById('ranking').innerHTML=d.clasificacion.map(p=>`<div class="rank"><b>${p.posicion}</b><span>${esc(p.nombre)}</span><span class="points">${p.puntos}</span></div>`).join('')||'<p class="muted">Esperando participantes.</p>';const key=`${d.pregunta?.id}-${d.fase}-${d.mi_resultado?.respondio}`;if(key===last){const t=document.getElementById('timer');if(t&&d.pregunta)t.textContent=d.pregunta.segundos_restantes;return}last=key;const b=document.getElementById('board');if(d.fase==='espera'){b.innerHTML='<div class="timer"><i class="fas fa-hourglass-half"></i></div><h1>Esperando al Profesor</h1><p class="muted">La trivia está lista para comenzar.</p>';return}if(['finalizada','cerrada'].includes(d.fase)){b.innerHTML=`<div class="timer"><i class="fas fa-trophy"></i></div><h1>Trivia finalizada</h1><p>${d.ganador?`${esc(d.ganador.nombre)} ganó con ${d.ganador.puntos} puntos.`:'Consulta la clasificación final.'}</p>`;return}if(d.fase==='resultado'){const ok=d.mi_resultado?.correcta,ans=(d.pregunta.respuestas_correctas||[]).map(v=>label(v,d.pregunta)).join(', ');b.innerHTML=`<div class="feedback ${ok?'correct':'incorrect'}"><h1>${ok?'¡Correcto!':'Respuesta incorrecta'}</h1><p>Sumaste <b>${d.mi_resultado?.puntos_sumados??0}</b> · Total: <b>${d.mi_resultado?.puntos_totales??0}</b></p><p>Respuesta correcta: ${esc(ans)}</p>${d.pregunta.explicacion?`<small>${esc(d.pregunta.explicacion)}</small>`:''}</div>`;return}if(!d.pregunta){b.innerHTML='<h1>Preparando pregunta…</h1>';return}const q=d.pregunta;if(d.mi_resultado?.respondio){b.innerHTML=`<div class="timer" id="timer">${q.segundos_restantes}</div><h1>Respuesta guardada</h1><p class="muted">Esperando a tus compañeros.</p>`;return}let fields='';if(q.tipo==='respuesta_directa')fields='<input type="text" name="respuesta" maxlength="1000" required autocomplete="off">';else{let opts=q.tipo==='verdadero_falso'?{true:'Verdadero',false:'Falso'}:(q.opciones||{}),multi=q.tipo==='seleccion_multiple';fields=`<div class="options">${Object.entries(opts).map(([k,v])=>`<label class="option"><input type="${multi?'checkbox':'radio'}" name="respuesta${multi?'[]':''}" value="${esc(k)}" ${multi?'':'required'}> ${esc(v)}</label>`).join('')}</div>`}b.innerHTML=`<div class="timer" id="timer">${q.segundos_restantes}</div><h1>${esc(q.enunciado)}</h1><form id="answer">${fields}<button class="btn">Responder</button></form>`;document.getElementById('answer').onsubmit=send}
async function send(e){e.preventDefault();const f=new FormData(e.target),many=f.getAll('respuesta[]'),answer=many.length?many:f.get('respuesta');e.target.querySelector('button').disabled=true;const r=await fetch(answerUrl,{method:'POST',headers:{'Content-Type':'application/json','Accept':'application/json','X-CSRF-TOKEN':csrf},body:JSON.stringify({respuesta:answer})}),d=await r.json();if(!r.ok||!d.success){alert(d.message||'No se pudo guardar');return}render(d)}
async function reconnect(){const token=localStorage.getItem(tokenKey);if(!token)return false;const r=await fetch(reconnectUrl,{method:'POST',headers:{'Content-Type':'application/json','Accept':'application/json','X-CSRF-TOKEN':csrf},body:JSON.stringify({reconexion_token:token})}),d=await r.json();if(r.ok&&d.success){localStorage.setItem(tokenKey,d.reconexion_token);return true}return false}
async function poll(){try{let r=await fetch(stateUrl,{headers:{Accept:'application/json'},cache:'no-store'});if(r.status===422&&await reconnect())r=await fetch(stateUrl,{headers:{Accept:'application/json'},cache:'no-store'});const d=await r.json();if(!r.ok||!d.success)throw Error();render(d);document.getElementById('connection').textContent='Sincronizado'}catch{document.getElementById('connection').textContent='Reconectando…'}}render(initial);setInterval(poll,1000);
</script></body></html>
